namespace Fanex.BetList.Core.UnitTest.Builder.ChoiceBuilder
{
    using Fanex.BetList.Core.Builder.ChoiceBuilder;
    using Fanex.BetList.Core.UnitTest.Templates;
    using Fanex.BetList.Core.UnitTest.Ultils.Enums;
    using NUnit.Framework;

    public class Choice1334Test
    {
        private ChoiceCreator _choiceCreator;
        private const string BetTeamHandicap = "/div/span[1]/span[2][@class=\"handicap\"]";

        [SetUp]
        public void Setup()
        {
            _choiceCreator = new ChoiceCreator(new Choice1334(), BetTypes.SetXGameYAndGameYAdd1Points);
        }

        [Test]
        public void Ticket_ShowSpanHandicapIsHandicap1()
        {
            // Act
            string actualValue = _choiceCreator.GetFirstChildInnerHtml(BetTeamHandicap);

            // Assert
            string expected = string.Format(" {0}", _choiceCreator.Ticket.Handicap1);
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void BetTeamOfTicketIs1_ShowBetTeamIsSpanUnder()
        {
            // Arrange
            _choiceCreator.Ticket.BetTeam = "1";

            // Act
            string actualValue = _choiceCreator.GetFirstChildOuterHtml(ChoiceXPath.BetTeam);

            // Assert
            string expected = string.Format("<span class=\"underdog\">{0}</span>", ChoiceTemplate.Under);
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void BetTeamOfTicketIs2_ShowBetTeamIsSpanOver()
        {
            // Arrange
            _choiceCreator.Ticket.BetTeam = "2";

            // Act
            string actualValue = _choiceCreator.GetFirstChildOuterHtml(ChoiceXPath.BetTeam);

            // Assert
            string expected = string.Format("<span class=\"favorite\">{0}</span>", ChoiceTemplate.Over);
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void BetTeamOfTicketIsEmpty_ShowBetTeamIsSpanExactly()
        {
            // Arrange
            _choiceCreator.Ticket.BetTeam = string.Empty;

            // Act
            string actualValue = _choiceCreator.GetFirstChildOuterHtml(ChoiceXPath.BetTeam);

            // Assert
            string expected = string.Format("<span class=\"underdog\">{0}</span>", ChoiceTemplate.Exactly);
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void Ticket_ShowSpanBetTypeName()
        {
            // Act
            string actualHtml = _choiceCreator.GetOuterHtml(ChoiceXPath.BetType);

            // Assert
            string expectedHtml = string.Format(ChoiceTemplate.BetType, _choiceCreator.TicketHelperStub.GetBetTypeNameById(_choiceCreator.Ticket.BetTypeId, _choiceCreator.Ticket.BetId));
            Assert.AreEqual(expectedHtml, actualHtml);
        }
    }
}